def redirect_after_login(next_url, default="/home"):
    """Return where to send the user after a successful login.

    `next_url` comes from the ?next= query parameter of the login page.
    """
    if not next_url:
        return default

    # Reject URLs starting with /api or /static
    if next_url.startswith("/api") or next_url.startswith("/static"):
        return default

    # Reject any URL containing ..
    if ".." in next_url:
        return default

    return next_url

