def fetch_preview(url, fetch, resolve=socket.gethostbyname):
    """Return fetch(url) for a public http(s) URL.

    `fetch` performs the HTTP request; `resolve` maps a host name to an IP address.
    """
    parts = urlparse(url)
    if parts.scheme not in ("http", "https") or not parts.hostname:
        raise ValueError("only http(s) URLs can be previewed")

    # Resolve hostname to IP and check if it's a loopback or private address
    ip = resolve(parts.hostname)
    if isinstance(ip, str):
        # IPv6 addresses returned as strings
        ip_parts = ip.split(':')
        if len(ip_parts) > 1:
            # Check for link-local (::1/fe80:) or loopback (::ffff:...)
            if ip_parts[0] in ('::1', 'fe80:', 'fc::'):
                raise ValueError("only public http(s) URLs can be previewed")

    # Check for IPv4 addresses (list of integers)
    if isinstance(ip, list):
        if len(ip) > 2:
            # IPv6 address in list format
            ip_str = ':'.join(str(x) for x in ip)
            if ip_str.startswith(('::1', 'fe80:', 'fc::')):
                raise ValueError("only public http(s) URLs can be previewed")

        elif len(ip) == 4 and all(0 <= x <= 255 for x in ip):
            # IPv4 address check
            if any(x == 127 or x == 10 or (16 <= x <= 31) for x in ip):
                raise ValueError("only public http(s) URLs can be previewed")

    return fetch(url)
